b:if.script:
//
{"@context":"https://schema.org","@type":"WebSite","name":"English Hub","url":"https://www.englishhub.co.in/","description":"English learning and teaching resources for ESL learners, teachers and examination preparation."}
//

head.b:skin:
:root{--bg:#f5f7fa;--card:#fff;--soft:#eef3f8;--text:#172033;--muted:#66758a;--line:#dfe5ec;--blue:#1769e0;--blue2:#0e4fae;--navy:#162235;--max:1180px;--shadow:0 8px 28px rgba(17,32,53,.07)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;line-height:1.6}a{color:inherit;text-decoration:none}img{max-width:100%;height:auto}button,input,textarea,select{font:inherit}.wrap{width:min(var(--max),calc(100% - 40px));margin:auto}.topbar{background:var(--navy);color:#dbe5f0;font-size:12px}.topbar .wrap{min-height:34px;display:flex;align-items:center;justify-content:space-between}.top-links ul,.menu ul,.footer-links ul{list-style:none;margin:0;padding:0;display:flex;gap:16px;align-items:center}.top-links a{color:#dbe5f0}.site-header{background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:50}.head{min-height:72px;display:flex;align-items:center;gap:25px}.brand{display:flex;align-items:center;gap:10px}.mark{width:42px;height:42px;border:2px solid var(--text);display:grid;place-items:center;font-size:14px;font-weight:950}.brand-name{font-size:21px;font-weight:950;letter-spacing:-.03em}.brand-name span{color:var(--blue)}.menu{margin-left:auto}.menu ul{gap:2px}.menu a{display:block;padding:10px 12px;border-radius:8px;font-size:13px;font-weight:800}.menu a:hover{background:var(--soft);color:var(--blue)}.search-toggle{border:1px solid var(--line);background:#fff;border-radius:9px;width:40px;height:40px;cursor:pointer;font-size:20px}.mobile-menu{display:none}.search-panel{display:none;border-top:1px solid var(--line);padding:10px 0}.search-panel.open{display:block}.search{display:flex;background:#fff;border:1px solid #cbd7e4;border-radius:11px;padding:5px;max-width:720px}.search input{flex:1;min-width:0;border:0;outline:0;padding:12px}.search button{border:0;background:var(--blue);color:#fff;border-radius:8px;padding:0 20px;font-weight:900}.ad-area{padding:14px 0}.ad-slot{min-height:90px;background:#fff;border:1px solid var(--line);border-radius:10px;display:flex;align-items:center;justify-content:center;overflow:hidden}
.hero{padding:60px 0 54px;background:linear-gradient(135deg,#eef5ff,#fff 58%,#fff8df);border-bottom:1px solid var(--line)}.hero-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:50px;align-items:center}.eyebrow{margin:0 0 12px;color:var(--blue2);font-size:12px;font-weight:900;letter-spacing:.13em;text-transform:uppercase}.hero h1{margin:0;font-size:clamp(42px,5.6vw,68px);line-height:.98;letter-spacing:-.06em}.hero h1 span{color:var(--blue)}.hero-copy{max-width:700px;margin:20px 0 25px;color:var(--muted);font-size:18px}.hero .search{max-width:720px}.quick{display:flex;flex-wrap:wrap;gap:8px;margin-top:13px}.quick a,.topic a{background:#fff;border:1px solid #d7e0ea;border-radius:999px;padding:6px 10px;font-size:12px;font-weight:800;color:#31516f}.hero-card{background:var(--navy);color:#fff;border-radius:18px;padding:28px;box-shadow:0 18px 45px rgba(22,34,53,.16)}.hero-card small{color:#a9c8ff;font-weight:900;letter-spacing:.13em;text-transform:uppercase}.hero-card h2{margin:8px 0 15px;font-size:24px}.hero-card ul{list-style:none;margin:0;padding:0}.hero-card li{border-top:1px solid rgba(255,255,255,.14);padding:14px 0}.hero-card li:first-child{border-top:0;padding-top:0}.hero-card b{display:block;font-size:15px}.hero-card span{display:block;color:#b9c8d9;font-size:12px;margin-top:3px}
.section{padding:50px 0}.section.alt,.latest{background:#fff;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:22px}.section-head h2,.page-title{margin:0;font-size:29px;line-height:1.15;letter-spacing:-.04em}.section-head p{margin:6px 0 0;color:var(--muted);font-size:14px}.section-head>a{color:var(--blue);font-size:13px;font-weight:900}.resource-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.resource{background:#fff;border:1px solid var(--line);border-radius:14px;padding:21px;min-height:165px;transition:.18s}.resource:hover{transform:translateY(-2px);box-shadow:var(--shadow);border-color:#c4d5e9}.icon{width:38px;height:38px;border-radius:10px;background:#eaf2ff;color:var(--blue);display:grid;place-items:center;font-weight:950;margin-bottom:14px}.resource h3{margin:0 0 5px;font-size:16px}.resource p{margin:0;color:var(--muted);font-size:13px;line-height:1.5}.audience{display:grid;grid-template-columns:1fr 1fr;gap:16px}.aud-card{border:1px solid var(--line);border-radius:17px;padding:28px;background:#fff;min-height:190px}.aud-card.dark{background:var(--navy);border-color:var(--navy);color:#fff}.aud-label{font-size:11px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;color:var(--blue)}.dark .aud-label{color:#a9c8ff}.aud-card h3{margin:7px 0;font-size:22px}.aud-card p{margin:0;color:var(--muted);max-width:600px}.dark p{color:#c7d3e1}.aud-card a{display:inline-block;margin-top:20px;color:var(--blue);font-size:13px;font-weight:900}.dark a{color:#fff}.exam-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.exam{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;display:flex;justify-content:space-between;gap:15px}.tag{display:inline-block;background:#edf3ff;color:var(--blue2);border-radius:99px;padding:4px 8px;font-size:10px;font-weight:900;text-transform:uppercase}.exam h3{margin:8px 0 5px;font-size:17px}.exam p{margin:0;color:var(--muted);font-size:13px}.arrow{color:var(--blue);font-size:21px}.topic{display:flex;flex-wrap:wrap;gap:8px}.topic a{background:#f5f8fc}.blog-wrap{padding:0 0 48px}.blog-shell{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:24px}.post-outer{background:#fff;border:1px solid var(--line);border-radius:15px;padding:27px;margin:0 0 17px}.post-title{font-size:clamp(29px,4vw,43px);line-height:1.12;letter-spacing:-.045em;margin:0 0 10px}.post-title a:hover{color:var(--blue)}.post-header,.post-footer{color:var(--muted);font-size:12px}.post-body{font-size:16px;color:#344054;overflow-wrap:anywhere}.post-body h2,.post-body h3{color:var(--text);line-height:1.3}.post-body a{color:var(--blue);text-decoration:underline}.post-body table{width:100%;border-collapse:collapse;display:block;overflow-x:auto}.post-body th,.post-body td{border:1px solid var(--line);padding:8px}.post-body blockquote{border-left:4px solid var(--blue);background:#f4f7fb;padding:12px 17px;margin:20px 0}.side{display:grid;gap:16px}.side-card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:20px}.side-card h3{margin:0 0 12px;font-size:17px}.labels{display:flex;flex-wrap:wrap;gap:7px}.labels a{border:1px solid var(--line);border-radius:99px;padding:6px 9px;font-size:11px;color:#38536f}.pager{display:flex;justify-content:space-between;gap:10px;margin:25px 0}.pager a{background:#fff;border:1px solid var(--line);padding:10px 14px;border-radius:9px;color:var(--blue);font-weight:800}.footer{background:var(--navy);color:#d9e3ef;padding:44px 0 22px}.footer-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:30px}.footer-brand{font-size:20px;font-weight:950;color:#fff}.footer-copy{color:#aebdcd;font-size:13px;max-width:430px}.footer-title{font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.1em;color:#fff}.footer-links ul{display:block}.footer-links li{margin:7px 0}.footer-links a{color:#aebdcd;font-size:13px}.footer-links a:hover{color:#fff}.bottom{border-top:1px solid rgba(255,255,255,.12);margin-top:30px;padding-top:16px;display:flex;justify-content:space-between;color:#91a2b5;font-size:11px}
@media(max-width:980px){.hero-grid{grid-template-columns:1fr}.resource-grid{grid-template-columns:repeat(2,1fr)}.exam-grid{grid-template-columns:1fr 1fr}.footer-grid{grid-template-columns:1.5fr 1fr 1fr}.menu{display:none}.mobile-menu{display:block;margin-left:auto;border:1px solid var(--line);background:#fff;border-radius:9px;padding:8px 11px;cursor:pointer}.head .search-toggle{display:none}.mobile-menu:focus+.menu-mobile{display:block}.menu-mobile{display:none}.menu-mobile.open{display:block}.menu-mobile ul{list-style:none;margin:0;padding:8px 0}.menu-mobile li{border-bottom:1px solid var(--line)}.menu-mobile a{display:block;padding:11px 0;font-weight:800}}
@media(max-width:640px){.wrap{width:min(var(--max),calc(100% - 28px))}.top-links{display:none}.head{min-height:64px}.brand-name{font-size:18px}.mark{width:38px;height:38px}.hero{padding:43px 0 40px}.hero h1{font-size:clamp(40px,12vw,54px)}.hero-copy{font-size:16px}.hero .search{display:block}.hero .search button{width:100%;height:43px;margin-top:5px}.resource-grid,.audience,.exam-grid,.footer-grid{grid-template-columns:1fr}.resource{min-height:0}.aud-card{min-height:0}.section{padding:40px 0}.section-head{display:block}.section-head>a{display:inline-block;margin-top:9px}.blog-shell{grid-template-columns:1fr}.side{display:none}.post-outer{padding:20px}.bottom{display:block}.bottom span{display:block;margin-top:6px}.footer-grid>div:first-child{margin-bottom:8px}}
@media(prefers-color-scheme:dark){:root{--bg:#0e1622;--card:#151f2d;--soft:#1b293a;--text:#eef4fb;--muted:#a7b4c5;--line:#29384a;--navy:#08111e;--blue:#62a0ff;--blue2:#86b7ff;--shadow:0 10px 30px rgba(0,0,0,.3)}body{background:var(--bg)}.site-header,.mobile-nav{background:#111b29}.hero{background:linear-gradient(135deg,#15253b,#101923 60%,#302b16)}.search,.resource,.aud-card,.exam,.side-card,.post-outer,.ad-slot{background:var(--card)}.search input{color:var(--text)}.quick a{background:var(--card);border-color:var(--line)}.latest,.section.alt{background:#111b29}.post-body{color:#d5dfeb}.post-body blockquote{background:#1a2636}}
